// L'IA range et résume. Le code tranche : l'urgence et le responsable suivent des règles fixes et vérifiables.
const f = $('Configuration').first().json;
const brut = ($input.first().json.text || '').replace(/```json|```/g, '').trim();
let ia = {};
try { ia = JSON.parse(brut.slice(brut.indexOf('{'), brut.lastIndexOf('}') + 1)); } catch (e) { ia = {}; }
const TYPES = ['Contrat client', 'Contrat fournisseur ou partenaire', 'Contrat de travail et RH', 'Données personnelles (RGPD)', 'Litige ou réclamation', 'Question juridique simple'];
const type = TYPES.includes(ia.type) ? ia.type : 'Question juridique simple';
const echeance = f.echeance || '';
const aujourdhui = new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00Z');
const joursRestants = echeance ? Math.round((new Date(echeance + 'T00:00:00Z') - aujourdhui) / 86400000) : null;
// Règles d'urgence : Haute = litige ou échéance dans 2 jours au plus ; Moyenne = échéance dans 7 jours au plus, données personnelles ou contrat de travail ; Basse sinon
let urgence = 'Basse';
if (type === 'Litige ou réclamation' || (joursRestants !== null && joursRestants <= 2)) urgence = 'Haute';
else if ((joursRestants !== null && joursRestants <= 7) || type === 'Données personnelles (RGPD)' || ia.donnees_personnelles === true || type === 'Contrat de travail et RH') urgence = 'Moyenne';
const RESPONSABLE = { 'Litige ou réclamation': 'Head of Legal', 'Données personnelles (RGPD)': 'Head of Legal', 'Contrat de travail et RH': 'Juriste', 'Contrat client': 'Juriste', 'Contrat fournisseur ou partenaire': 'Juriste', 'Question juridique simple': 'Réponse type' };
const DELAI = { Haute: '24 heures', Moyenne: '3 jours ouvrés', Basse: '5 jours ouvrés' };
let manque = (ia.informations_manquantes || '').trim();
if (manque && !/[.!?]$/.test(manque)) manque += '.';
let resume = (ia.resume || f.demande.slice(0, 60)).trim().replace(/[.]$/, '');
resume = resume.charAt(0).toUpperCase() + resume.slice(1);
return [{ json: {
  prenom: f.prenom, equipe: f.equipe, demande: f.demande, document: f.document,
  echeance: echeance || null, jours_restants: joursRestants, type, resume, urgence, avis_ia: ia.urgence_proposee || '', raison: ia.raison || '',
  responsable: RESPONSABLE[type], delai: DELAI[urgence], informations_manquantes: manque, statut: manque ? "En attente d'informations" : 'Nouvelle',
  recue_le: new Date().toISOString().slice(0, 10)
} }];

