// Une relance seulement si l'échéance tombe dans les 2 jours ou est dépassée
const conf = $('Configuration des relances').first().json;
const aujourdhui = new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00Z');
const txt = (p) => ((p && (p.title || p.rich_text)) || []).map((t) => t.plain_text).join('');
return ($input.first().json.results || []).map((p) => {
  const pr = p.properties;
  const ech = pr['Échéance']?.date?.start;
  const jours = Math.round((new Date(ech + 'T00:00:00Z') - aujourdhui) / 86400000);
  return { demande: txt(pr['Demande']), responsable: pr['Responsable']?.select?.name || 'Legal', urgence: pr['Urgence']?.select?.name || '', echeance: ech, jours, url: p.url };
}).filter((d) => d.jours <= conf.jours_avant_echeance).sort((a, b) => a.jours - b.jours).map((d) => ({ json: d }));

